using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00016 : ControllerTestBase
    {
        [TestMethod]
        public void Should_Contain_Version_Placeholder_In_Base_Route_Of_Controller()
        {
            var noSecurity = (from controller in Controllers
                              from attribute in controller.Attributes.Where(a => a.Name.Contains("Route") && a.Arguments.All(a => a.DoesNotContain("v{version:apiVersion}")))
                              select new
                              {
                                  ErrorClass = controller.FullQualifiedName,
                                  Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Attribute:  {attribute.SyntaxTree}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     [Route(""v{{version:apiVersion}}/users"")]
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                              }).ToImmutableList();


            Assert.IsTrue(noSecurity.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00016

Please do not mixed different version inside one controller. One endpoint (controller) should only be responsible for one explicit version. Findings {noSecurity.Count}': {Environment.NewLine}{noSecurity.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
